--!strict
--[[
    Stores all internal and external Types for Dex
]]
export type Unsubscribe = () -> ()
export type Set<T> = {[T]: true}

export type MappingBinopMetamethod<Simple, Complex> =
    ((lhs: Complex, rhs: Complex) -> Complex)
    & ((lhs: Simple, rhs: Complex) -> Complex)
    & ((lhs: Complex, rhs: Simple) -> Complex)
export type Observable<T> = typeof(setmetatable(
    {} :: {
        _cachedValue: T,
        _getCurrent: () -> T,
        _createUpdateStream: (notifyChange: () -> ()) -> Unsubscribe,
        _closeUpdateStream: Unsubscribe?,
        _listeners: Set<(newValue: T) -> ()>,
        _destroyed: boolean?,
    },
    {} :: {
        __index: {
            _dectype: string,
            _decobservabletype: string,
            Subscribe: (self: Observable<T>, listener: (T) -> (),
                immediatelyCallListener: boolean?) -> Unsubscribe,
            Current: (self: Observable<T>) -> T,
            Destroy: (self: Observable<T>) -> (),
            Map: (self: Observable<T>, mappingFunction: (T) -> any) -> any,
        },
        __mul: MappingBinopMetamethod<T, Observable<T>>,
        __add: MappingBinopMetamethod<T, Observable<T>>,
        __sub: MappingBinopMetamethod<T, Observable<T>>,
        __div: MappingBinopMetamethod<T, Observable<T>>,
        __pow: MappingBinopMetamethod<T, Observable<T>>,
        __unm: (self: Observable<T>) -> Observable<T>,
    }
))
export type State<T> = Observable<T> & typeof(setmetatable(
    {} :: {
        _valueRef: {value: T},
        _notifyUpdate: (() -> ())?,
    },
    {} :: {__index: {
        Set: (self: State<T>, T) -> (),
    }}
))
export type StateRecord<T> = Observable<T> & typeof(setmetatable(
    {} :: {
        _valueRef: {value: T},
        _notifyUpdate: (() -> ())?,
        _notifyRecord: {[any]: {[() -> ()]: true}}
    },
    {} :: {__index: {
        Set: (self: StateRecord<T>, key: any, newValue: any) -> (),
        Current: (self: StateRecord<T>, atKey: any) -> any,
        Replace: (self: StateRecord<T>, T) -> (),
        Index: (self: StateRecord<T>, key: any) -> State<any>,
    }}
))
export type StateDict<K, V> = Observable<{[K]: V}> & typeof(setmetatable(
    {} :: {
        _valueRef: {value: {[K]: V}},
        _notifyUpdate: (() -> ())?,
        _notifyRecord: {[K]: {[() -> ()]: true}}
    },
    {} :: {__index: {
        Set: (self: StateDict<K, V>, key: any, newValue: any) -> (),
        Current: ((self: StateDict<K, V>, atKey: K) -> V)
            & ((self: StateDict<K, V>) -> {[K]: V}),
        Replace: (self: StateDict<K, V>, {[K]: V}) -> (),
        Index: (self: StateDict<K, V>, key: K) -> State<V>,
    }}
))
export type EasedObject<T> = Observable<T> & typeof(setmetatable(
    {} :: {
        _target: Observable<T>,
        _easingFrame: any,
    },
    {} :: {__index: {
        CurrentTarget: (self: EasedObject<T>) -> T,
        SetPosition: (self: EasedObject<T>, position: T) -> (),
        ResetVelocity: (self: EasedObject<T>) -> (),
    }}
))
export type Spring<T> = EasedObject<T> & typeof(setmetatable(
    {} :: {
        _angularFrequency: any, -- CanBeObservable<number>
    },
    {} :: {__index: { }}
))
export type AngleSpring<T> = Spring<T>
export type IntSpring<T> = Spring<T>
export type EasedValue<T> = EasedObject<T> & typeof(setmetatable(
    {} :: {
        _info: TweenInfo,
    },
    {} :: {__index: { }}
))
export type BaseTimer = Observable<number> & typeof(setmetatable(
    {} :: {
        -- Public
        Looped: boolean,
        -- Private
        _duration: number,
        _playState: State<{
            playing: boolean,
            startClockTime: number,
            resumeAtTime: number,
        }>,
        _startReactiveControlStream: (notifyUpdate: () -> ()) -> (() -> ())
    },
    {} :: {__index: {
        Play: (self: BaseTimer) -> (),
        Stop: (self: BaseTimer) -> (),
        Pause: (self: BaseTimer) -> (),
        SetTimePosition: (self: BaseTimer, position: number) -> (),
        Lerp: <T>(
            self: BaseTimer,
            startValue: T,
            goalValue: T
        ) -> Observable<T>,
        Alpha: (
            self: BaseTimer,
            startTime: number,
            endTime: number
        ) -> Observable<number>
    }}
))
export type TweenParams<T> = {
    info: TweenInfo,
    goal: T,
    start: T?,
    completed: (() -> ())?,
    cancelled: (() -> ())?,
}
export type Tween<T> = Observable<T> & typeof(setmetatable(
    {} :: {
        _lastDispatch: State<{
            params: TweenParams<T>,
            startClockTime: number,
            duration: number,
            completed: boolean,
        }>
    },
    {} :: {__index: {
        Play: (self: Tween<T>, props: TweenParams<T>) -> (),
    }}
))
export type Stopwatch = BaseTimer
export type Timer = BaseTimer
export type CanBeObservable<T = any> = T | Observable<T>
export type StopwatchProps = {
    duration: number?,
    isPlaying: CanBeObservable<boolean>?,
    playOnChange: Observable<any>?,
}
export type TimerProps = {
    duration: number,
    isPlaying: CanBeObservable<boolean>?,
    playOnChange: Observable<any>?,
}
export type ChildPath = string | number
export type ChildMap = CanBeObservable<{
    [any]: any--[[[ChildPath]: CanBeObservable<
        VirtualInstance | nil
    >]]
}>
export type VirtualInstanceTrace = {
    method: string,
    source: string?,
    traceback: {{
        identifier: string,
        line: number,
    }}
}
export type VirtualInstanceDirective = {
    _type: string,
    _payload: any,
    _trace: VirtualInstanceTrace?,
}
export type VirtualInstance = typeof(setmetatable(
    {} :: {
        _current: Instance?,
        _constructorType: string,
        _constructorTypeArgument: any,
        _combinedIsAChecks: {{
            className: string,
            trace: VirtualInstanceTrace?,
        }}?,
        _directives: {VirtualInstanceDirective},
        _reconciledNode: ReconciledNode?,
        _onReconciledNodeCallbacks: {[(ReconciledNode) -> ()]: boolean},
    },
    {} :: {__index: {
        _dectype: string,
        SetProperties: (
            self: VirtualInstance,
            propertyMap: {[string]: any}
        ) -> (),
        SetAttributes: (
            self: VirtualInstance,
            attributeMap: {[string]: any}
        ) -> (),
        AddTags: (
            self: VirtualInstance,
            tags: any
        ) -> (),
        Connect: (
            self: VirtualInstance,
            eventName: string,
            signal: (...any) -> ()
        ) -> (),
        OutProperty: (<T>(
            self: VirtualInstance,
            propertyName: string,
            initializedValue: T
        ) -> Observable<T>) & (
            self: VirtualInstance,
            propertyName: string
        ) -> Observable<any?>,
        OutInitialProperty: (<T>(
            self: VirtualInstance,
            propertyName: string,
            initializedValue: T
        ) -> Observable<T>) & (
            self: VirtualInstance,
            propertyName: string
        ) -> Observable<any?>,
        OutAttribute: (<T>(
            self: VirtualInstance,
            attributeName: string,
            initializedValue: T
        ) -> Observable<T>) & (
            self: VirtualInstance,
            attributeName: string
        ) -> Observable<any?>,
        OutInitialAttribute: (<T>(
            self: VirtualInstance,
            propertyName: string,
            initializedValue: T
        ) -> Observable<T>) & (
            self: VirtualInstance,
            attributeName: string
        ) -> Observable<any?>,
        OutInstance: (
            self: VirtualInstance
        ) -> Observable<any?>,
        AddChildren: (
            self: VirtualInstance,
            childMap: ChildMap
        ) -> (),
        MapChildren: <K, V>(
            self: VirtualInstance,
            input: Observable<{[K]: V}>,
            map: (key: K, value: V) -> any?
        ) -> (),
        MapChildrenByKey: <K, V>(
            self: VirtualInstance,
            input: Observable<{[K]: V}>,
            map: (key: K, value: Observable<V>) -> any?
        ) -> (),
        MapChildrenByValue: <K, V>(
            self: VirtualInstance,
            input: Observable<{[K]: V}>,
            map: (value: V, key: Observable<K>) -> any?
        ) -> (),
        FindChild: (
            self: VirtualInstance,
            className: string,
            childPath: ChildPath
        ) -> VirtualInstance,
        AddChild: (
            self: VirtualInstance,
            path: ChildPath,
            child: CanBeObservable<any>
        ) -> (),
        DestroyPremadeChildren: (
            self: VirtualInstance,
            filter: nil | string | ((child: Instance) -> boolean)
        ) -> (),
        OnMount: (
            self: VirtualInstance,
            callback: () -> ()
        ) -> (),
        OnUnmount: (
            self: VirtualInstance,
            callback: () -> ()
        ) -> (),
        Combine: (
            self: VirtualInstance,
            ...VirtualInstance
        ) -> (),
        SubscribeWhileMounted: <T>(
            self: VirtualInstance,
            input: Observable<T>,
            listener: (T) -> (),
            immediatelyCallListener: boolean?
        ) -> (),
    }}
))
export type ReconciledNode = {
    _connections: {RBXScriptConnection},
    _unsubscribes: {Unsubscribe},
    _instancesToCleanup: {Instance},
    _instance: Instance?,
    _instanceResolvedCallbacks: {[(Instance) -> ()]: boolean},
    _rootInstance: Instance,
    _childPath: string?,
    _dectype: string,
    _childMap: {[string]: ReconciledNode},
    _childCleanups: {[string]: () -> ()},
}
export type Symbol<Name> = typeof(setmetatable(
    {} :: {
        _name: Name,
        _usage: string?,
    },
    {} :: {__index: {
        _dectype: string,
    }, __tostring: (self: Symbol<Name>) -> string}
))
export type Root = typeof(setmetatable(
    {} :: {
        _instance: Instance,
        _reconciled: ReconciledNode?
    },
    {} :: {__index: {
        _dectype: string,
        Render: (self: Root, node: VirtualInstance) -> ReconciledNode,
        Unmount: (self: Root) -> (),
        Destroy: (self: Root) -> (),
    }}
))

return nil

--!strict

local Types = require(script.Parent.Types)
local State = require(script.Parent.Observables.State)

type VirtualInstanceTrace = Types.VirtualInstanceTrace
type VirtualInstance = Types.VirtualInstance
type Observable<T> = Types.Observable<T>
type CanBeObservable<T> = Types.CanBeObservable<T>
type ChildPath = Types.ChildPath
type ChildMap = Types.ChildMap

local VIRTUAL_INSTANCE_TRACING = true
local DEBUG_MAX_TRACEBACK_LENGTH = 3

local function getTrace(methodName: string, traceLevel: number): VirtualInstanceTrace?
    if not VIRTUAL_INSTANCE_TRACING then
        return nil
    end

    traceLevel += 1

    local source: string? = debug.info(traceLevel, "s")
    local traceback: {{
        identifier: string,
        line: number
    }} = {}
    if source then
        for i = 0, DEBUG_MAX_TRACEBACK_LENGTH - 1 do
            local traceLevelAtIndex = traceLevel + i
            if debug.info(traceLevelAtIndex, "s") ~= source then
                break
            end
            local ident = debug.info(traceLevelAtIndex, "n")
            local line = debug.info(traceLevelAtIndex, "l")
            if not ident or not line then
                break
            end
            table.insert(traceback, {
                identifier = ident,
                line = line,
            })
        end
    end
    local trace: VirtualInstanceTrace? = {
        method = methodName,
        source = source,
        traceback = traceback,
    }
    return trace
end
local function assertNotYetMounted(virtualInstance: VirtualInstance)
    if table.isfrozen(virtualInstance :: any) then
        error(
            "Cannoy modify a VirtualInstance after it has been mounted. " .. 
            "Please verify your code to make sure you are only defining " ..
            "properties, attributes, tags, etc. before mounting the " .. 
            "VirtualInstance (See Dex docs). You should utilize Observables " ..
            "instead of modifying a VirtaulInstance after it is mounted.",
            2
        )
    end
end

--[=[
    @class VirtualInstance
    VirtualInstances are the basic building blocks for Dex applications.

    VirtualInstances are "Mounted" by Dex's reconciler engine,
    creating/destoying/modifying these real instances automatically as needed.

    ## Constructors
    ---

    ### Dex.New
    ```lua
    Dex.New(
        className: string,
        props: {[string]: any}?,
        children: {[any]: CanBeObservable<VirtualInstance?>}
    ) -> VirtualInstance
    ```

    Creates a new [VirtualInstance] that represents a newly-created Roblox
    Instance (via `Instance.new(className)`).

    ---

    ### Dex.Clone
    ```lua
    Dex.Clone(
        template: Instance | VirtualInstance,
        props: {[string]: any}?,
        children: {[any]: CanBeObservable<VirtualInstance?>}
    ) -> VirtualInstance
    ```
    Creates a new [VirtualInstance] that represents a cloned Roblox Instance
    from a given template instance (via `template:Clone()`).

    ---

    ### Dex.Premade
    ```lua
    Dex.Premade(
        className: stirng,
        props: {[string]: any}?,
        children: {[any]: CanBeObservable<VirtualInstance?>}
    ) -> VirtualInstance
    ```

    Creates a new VirtualInstance that represents a pre-existing Roblox Instance
    to be modified by Dex.

    If passed into the the Render function for a [Dex.Root] component, the root
    instance will be used used.
]=]
local VirtualInstance = {}
VirtualInstance.__index = {}
VirtualInstance.__index._dectype = "VirtualInstance"

--[=[
    @method SetProperties
    @within VirtualInstance
    @param propertyMap {[string]: CanBeObservable<any>}

    Adds properties to be rendered on the instance when it is reconciled.

    Multiple calls to this function will merge the provided property map with
    the existing one, prioritizing the later call.

    Values in the propertyMap can have multiple possible types, which are each
    handled differently:

    - A **Static Value** (number, boolean, string, UDim2, etc.) to be assigned
    right as the VirtualInstance is rendered
    - An **Observablue Value** to be assigned as the VirtualInstance is
    Rendered, as well as when the Observable value changes
    - A **`Dex.Nil`** symbol, which assigns a property to `nil` when rendered
    - A **function** which represents a listener to connect to an event while
    the VirtualInstance is rendered
    - Another **VirtualInstance**, which references an instance property to be
    assigned. This is useful for ViewportFrames, for example, where a camera
    must both be created underneath the ViewportFrame, and assigned as the
    CurrentCamera property within the same frame.
]=]
function VirtualInstance.__index.SetProperties(
    self: VirtualInstance,
    propertyMap: {[string]: any}
): ()
    assertNotYetMounted(self)
    table.insert(self._directives, {
        _type = "Properties",
        _payload = propertyMap,
        _trace = getTrace("VirtualInstance:SetProperties", 1),
    })
end

--[=[
    @method SetAttributes
    @within VirtualInstance
    @param attributeMap {[string]: CanBeObservable<any>}

    Adds attributes to be rendered on the instance when it is reconciled.

    Multiple calls to this function will merge the provided attribute map with
    the existing one, prioritizing the latest calls.
]=]
function VirtualInstance.__index.SetAttributes(
    self: VirtualInstance,
    attributeMap: {[string]: CanBeObservable<any>}
): ()
    assertNotYetMounted(self)
    table.insert(self._directives, {
        _type = "Attributes",
        _payload = attributeMap,
        _trace = getTrace("VirtualInstance:SetAttributes", 1),
    })
end

--[=[
    @method AddTags
    @within VirtualInstance
    @param tags CanBeObservable<{string}>

    Adds tags to the Virtual Instance when it is reconciled. Multiple calls to
    this function will add extra tags to the VirtualInstance if they do not
    exist.
]=]
function VirtualInstance.__index.AddTags(
    self: VirtualInstance,
    tags: CanBeObservable<{string}>
): ()
    assertNotYetMounted(self)
    table.insert(self._directives, {
        _type = "TagList",
        _payload = tags,
        _trace = getTrace("VirtualInstance:AddTags", 1),
    })
end

--[=[
    @method Connect
    @within VirtualInstance
    @param eventName string
    @param listener (...any) -> ()

    Adds an event listener to the Virtual Instance, which will automatically
    be connected and disconnected as the VirtualInstance is reconciled.
]=]
function VirtualInstance.__index.Connect(
    self: VirtualInstance,
    eventName: string,
    listener: (...any) -> ()
): ()
    assertNotYetMounted(self)
    table.insert(self._directives, {
        _type = "Connect",
        _payload = {
            event = eventName,
            listener = listener,
        },
        _trace = getTrace("VirtualInstance:Connect", 1),
    })
end

--[=[
    @method OutProperty
    @within VirtualInstance
    @param propName string
    @param initialValue T
    @return Observable<T>

    Creates an Observable object that updates to the current value of an
    property on the virtual instance once when it is mounted, and listens to
    updates on this property.

    Give initialValue a type annotation if initializing to nil
    (e.g. vInst:OutProperty("Adornee", nil :: Instance?)()
]=]
function VirtualInstance.__index.OutProperty(
    self: VirtualInstance,
    propertyName: string,
    initialValue: any
): Observable<any>
    assertNotYetMounted(self)
    local outState = State.new(initialValue)
    table.insert(self._directives, {
        _type = "OutProperty",
        _payload = {
            property = propertyName,
            state = outState,
            once = false,
        },
        _trace = getTrace("VirtualInstance:OutProperty", 1),
    })
    return outState
end

--[=[
    @method OutInitialProperty
    @within VirtualInstance
    @param propName string
    @param initialValue T
    @return Observable<T> - An observable with the same output type as initialValue.

    Creates an Observable object that updates to the original value of an
    property on the virtual instance once when it is mounted. This is useful
    for referencing properties on a premade instance without hardcoding them in
    a Dex component.

    Give initialValue a type annotation if initializing to nil
    (e.g. vInst:OutInitialProperty("Adornee", nil :: Instance?))
]=]
function VirtualInstance.__index.OutInitialProperty(
    self: VirtualInstance,
    propertyName: string,
    initialValue: any
