    assertNotYetMounted(self)
    local outState = State.new(initialValue)
    table.insert(self._directives, {
        _type = "OutProperty",
        _payload = {
            property = propertyName,
            state = outState,
            once = true,
        },
        _trace = getTrace("VirtualInstance:OutInitialProperty", 1),
    })
    return outState
end

